function saveSvg(file_name) {
	let svgStr = `<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">\n`;

	svgStr += `<g id="red" stroke="red" fill="none">\n`;
	for (const poly of polys1) {
		svgStr += poly.toSVG();
	}
	svgStr += `</g>\n`;

	svgStr += `<g id="blue" stroke="blue" fill="none">\n`;
	for (const poly of polys2) {
		svgStr += poly.toSVG();
	}
	svgStr += `</g>\n`;

	svgStr += `</svg>`;

	save(svgStr.split("\n"), file_name + '.svg.txt');
}

