const LERPS = 40; 
let ANCHOR = 5;
let crv1, crv2;
const { Point, Line, Polygon } = EpiShapeSvg;
const { EpiColors } = EpiColorsPckg;
let epiColors;
let polys1, polys2;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("lerping between 2 curves");
	loop();
	noFill();
	stroke(212);
	strokeWeight(2);

	const DLT = height/2;
	let GN = ANCHOR /* * 1+3 */; ANCHOR = ~~random(4, 11); // next num anchor

	epiColors = new EpiColors();
	epiColors.BG = EpiColors.getAdjustedBrightness(EpiColors.getAdjustedSaturation(epiColors.BG, 2), 0.35);
	// console.log(epiColors)

	// crv1: random x + y distribution
	crv1 = {
		pts: [
			0, random(0.4, 0.6)*height,
			random(2, 2)*width, random(0.35)*height,
			random(-1, -1)*width, random(0, -0.35)*height,
			width, random(0.2, 0.8)*height
		],
		xs: genXs(GN),
		ys: genYs(GN),
		clr: epiColors.getRandomClr()
	}
	// for (let i = 1; i < bez1.pts.length; i+=2) bez1.pts[i] -= DLT;

	// crv2: ordered x, y flattend and increased by 1/3 height
	crv2 = {
		pts: [
			0, height/2,
			random(0.3, 0.6)*width, random(0.35, 0.65)*height,
			random(0.4, 0.7)*width, random(0.35, 0.65)*height,
			width, height/2
		],
		xs: [...crv1.xs],
		ys: [...crv1.ys],
		clr: epiColors.getRandomClr()
	}
	crv2.xs.sort();
	for (let i = 1; i < crv2.pts.length; i+=2) crv2.pts[i] += DLT;
	// for (let i = 1; i < bez2.ys.length; i++) bez2.ys[i] += DLT;
	let minY = Infinity, maxY = -Infinity;
	for (let i = 1; i < crv2.ys.length; i++) {
		if (crv2.ys[i] > maxY) maxY = crv2.ys[i];
		if (crv2.ys[i] < minY) minY = crv2.ys[i];
	}
	for (let i = 1; i < crv2.ys.length; i++) crv2.ys[i] = map(crv2.ys[i], minY, maxY, DLT+minY/2, DLT+maxY/2);

	// console.log(crv2, crv2)
	// noLoop() removed for animation
}

function draw() {
	blendMode(BLEND)
	background(epiColors.BG);
	blendMode(ADD);

	polys1 = [], polys2 = [];

	// drawBez(crv2);
	const LEN = min(crv1.pts.length, crv2.pts.length)
	const HLF = ~~(LERPS/2);
	for (let i = 0; i < LERPS; i++) {
		const f = i/(LERPS-1);
		const pts = [], xs = [], ys = [];
		for (let j = 0; j < LEN; j++) pts.push(lerp(crv1.pts[j], crv2.pts[j], f));
		for (let j = 0; j < crv1.xs.length; j++) {
			xs.push(lerp(crv1.xs[j], crv2.xs[j], f));
			ys.push(lerp(crv1.ys[j], crv2.ys[j], f));
		}
		const crv = {
			pts, xs, ys,
			clr: lerpColor(crv1.clr, crv2.clr, f)
		}
		// console.log(crv)
		drawCurve(crv);
		const poly = new Polygon(getCurvePts(crv));
		if (i <= HLF) {		
			// first half just add
			polys1.push(poly);
		} else {
			// 2nd half reverse order and switch order for 2nd half
			poly.pts[poly.pts.length - 1].reverse();
			polys2.unshift(poly);
			// polygons.splice(HLF, 0, poly);
		}
	}
	polys1.reverse();
	polys2.reverse();

	// console.log(polygons.length)
}

function getCurvePts(crv, debug = false) {
	var pts = [];
	for (let i = 0; i < crv.xs.length-3; i++) {
		const x1 = crv.xs[i+0], y1 = crv.ys[i+0];
		const x2 = crv.xs[i+1], y2 = crv.ys[i+1];
		const x3 = crv.xs[i+2], y3 = crv.ys[i+2];
		const x4 = crv.xs[i+3], y4 = crv.ys[i+3];
		// console.log("*", i, x1, x2, x3, x4);
		const len = dist(x2, y2, x3, y3);
		const num = ~~max(2, len/5);
		for (let j = 0; j < num; j++) {
			var f = j/num;
			const x = curvePoint(x1, x2, x3, x4, f);
  		const y = curvePoint(y1, y2, y3, y4, f);
			// circle(x, y, 5);
			pts.push({x, y});
		}
	}
	var x = crv.xs[crv.xs.length-2];
	var y = crv.ys[crv.ys.length-2];
	// circle(x, y, 5);
	pts.push({x, y});

	if (false) {
		push();
		noFill();
		strokeWeight(1.5);
		stroke(255);
		beginShape();
		for (const p of pts) vertex(p.x, p.y);
		endShape();
		pop();
	}

	return pts;
}

function drawCurve(crv, debug = false) {
	if (debug) {
		push();
		for (let i=0; i<crv.pts.length; i+=2) circle(crv.pts[i], crv.pts[i+1], 6)
		strokeWeight(1)
		// line(...bez.p1, ...bez.p2)
		// line(...bez.p3, ...bez.p4)
		strokeWeight(3)
		pop();
	}
	stroke(crv.clr);
	// bezier(...bez.pts);

	beginShape();
	if (false) {
		vertex(bez.pts[0], bez.pts[1]);
		bezierVertex(bez.pts[2], bez.pts[3], bez.pts[4], bez.pts[5], bez.pts[6], bez.pts[7]);
	} else {
		vertex(crv.xs[0], crv.ys[0]);
		if (true)
		for (let i = 1; i < crv.xs.length; i++) {
			// console.log(i);
			curveVertex(crv.xs[i], crv.ys[i]);
		}


		if (false)
		for (let i = 1; i < bez.xs.length; i+=3) {
			// console.log(i);
			bezierVertex(bez.xs[i], bez.ys[i], bez.xs[i+1], bez.ys[i+1], bez.xs[i+2], bez.ys[i+2]);
		}
	}
	endShape();
}

function mousePressed() {
	if (mouseButton != RIGHT) setup();
}

function genXs(num) {
	const arr = [];
	for (let i = 0; i < num; i++) arr.push(random()*width); 
	arr[0] = width * random(0.1);
	arr[num-1] = width * random(0.9, 1);
	return arr;
}
function genYs(num) {
	var arr = [];
	for (let i = 0; i < num; i++) arr.push(random(0.5)*height); 
	arr[0] = random(0.4, 0.6)*height;
	arr[num-1] = random(0.2, 0.8)*height;
	return arr;
}
